def is_balanced(s):
    stack = []
    in_string = None
    i = 0
    while i < len(s):
        c = s[i]
        if in_string:
            if c == '\\':
                i += 1
            elif c == in_string:
                in_string = None
        else:
            if c == "'" or c == '"':
                in_string = c
            elif c in '([{':
                stack.append(c)
            elif c in ')]}':
                if not stack:
                    return False
                top = stack.pop()
                if (c == ')' and top != '(') or \
                   (c == ']' and top != '[') or \
                   (c == '}' and top != '{'):
                    return False
        i += 1
    return len(stack) == 0
